mapper.select:
select * from (
select a.*,b.machine_name
from t_cd90_loss_setting a
left join T_CD90_MACHINE_INFO b
on a.machine_id = b.id and b.del_flag = '0'
where a.del_flag = '0'

    and INSTR(cloth_code, #{clothCode,jdbcType=VARCHAR}) > 0

and machine_id = #{machineId}
and loss_rate = #{lossRate}

    order by a.CREATE_TIME desc

) t


    order by ${orderStr}

select count(1)
from t_cd90_loss_setting
where del_flag = '0'
and cloth_code = #{clothCode}
and cloth_code is null
and machine_id = #{machineId}
and machine_id is null
and id != #{id}

mapper.update:
update t_cd90_loss_setting
cloth_code = #{clothCode}, machine_id = #{machineId,jdbcType=VARCHAR}, loss_rate = #{lossRate}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark},
where id = #{id}

mapper.delete:
update t_cd90_loss_setting
set del_flag='1'
where id = #{id}
